import sys
sys.setrecursionlimit(300000)

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))

        adj = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

        if n == 2:
            results.append("1")
            continue

        parent = [0] * (n + 1)
        order = []
        stack = [1]
        visited = [False] * (n + 1)
        visited[1] = True

        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    stack.append(v)

        degree = [len(adj[i]) for i in range(n + 1)]
        is_leaf = [False] * (n + 1)
        for i in range(1, n + 1):
            if i != 1:
                if len(adj[i]) == 1:
                    is_leaf[i] = True
            else:
                if len(adj[i]) == 0:
                    is_leaf[i] = True

        def count_children_leaves(u):
            cnt = 0
            for v in adj[u]:
                if v != parent[u]:
                    if is_leaf[v]:
                        cnt += 1
            return cnt

        def is_bud(u):
            if u == 1:
                return False
            if not is_leaf[u]:
                c = count_children_leaves(u)
                if c > 0 and c == len([v for v in adj[u] if v != parent[u]]):
                    return True
            return False

        moved = [False] * (n + 1)

        for u in reversed(order):
            if u == 1:
                continue
            p = parent[u]
            if moved[u]:
                continue

            children_in_tree = [v for v in adj[u] if v != parent[u]]
            all_children_leaves = all(is_leaf[v] for v in children_in_tree)

            if children_in_tree and all_children_leaves and u != 1:
                moved[u] = True
                for v in children_in_tree:
                    is_leaf[v] = False
                is_leaf[u] = False

        leaf_count = 0
        for i in range(1, n + 1):
             children_in_tree = [v for v in adj[i] if v != parent[i]]
             if not children_in_tree:
                 leaf_count += 1

        results.append(str(leaf_count))

    sys.stdout.write('\n'.join(results) + '\n')

solve()
